const segmentToSourcePagePathname = (segment: Segment): string => {
  if (typeof segment === 'string') {
    if (segment === 'children') return ''
    if (segment.startsWith(PAGE_SEGMENT_KEY)) return 'page'
    return segment
  }

  const [paramName, , dynamicParamType] = segment

  switch (dynamicParamType) {
    case 'c':
      return `[...${paramName}]`
    case 'ci(..)(..)':
      return `(..)(..)[...${paramName}]`
    case 'ci(.)':
      return `(.)[...${paramName}]`
    case 'ci(..)':
      return `(..)[...${paramName}]`
    case 'ci(...)':
      return `(...)[...${paramName}]`
    case 'oc':
      return `[[...${paramName}]]`
    case 'd':
      return `[${paramName}]`
    case 'di(..)(..)':
      return `(..)(..)[${paramName}]`
    case 'di(.)':
      return `(.)[${paramName}]`
    case 'di(..)':
      return `(..)[${paramName}]`
    case 'di(...)':
      return `(...)[${paramName}]`
    default:
      dynamicParamType satisfies never
      return `[${paramName}]`
  }
