  try {
    // HEAD request to the current page with the RSC header, so we're
    // testing connectivity to the same endpoint that navigations use.
    await fetch(location.href, {
      method: 'HEAD',
      headers: { [RSC_HEADER]: '1' },
      signal: controller.signal,
